/// <summary>
/// Extension of class <c>ReturnTableButtonStateProvider</c>.
/// </summary>
[ExtensionOf(classStr(ReturnTableButtonStateProvider))]
final class METReturnTableButtonStateProvider_Extension
{
    private boolean metApplyDispositionCodeEnabled;

}

Method.Source:
/// <summary>
/// Gets and sets disposition code check.
/// </summary>
/// <param name = "_metApplyDispositionCodeEnabled">Disposition code check.</param>
/// <returns>Disposition code check.</returns>
public boolean parmApplyDispositionCodeEnabled(boolean _metApplyDispositionCodeEnabled = metApplyDispositionCodeEnabled)
{
    metApplyDispositionCodeEnabled = _metApplyDispositionCodeEnabled;
    return metApplyDispositionCodeEnabled;
}

/// <summary>
/// Initializes header action.
/// </summary>
public void initHeaderActions()
{
    next initHeaderActions();

    metApplyDispositionCodeEnabled = this.metcheckRuleApplyDispositionCode();
}

/// <summary>
/// Checks for rule for applying disposition code.
/// </summary>
/// <returns>True if valid; otherwise, false.</returns>
private boolean metcheckRuleApplyDispositionCode()
{
    SalesLine checkSalesLine;

    select firstonly RecId from checkSalesLine
        where checkSalesLine.SalesId == salesTable.SalesId
        &&    checkSalesLine.ReturnDispositionCodeId == '';

    return (checkSalesLine.RecId != 0);
}
